INSERT INTO public.requirement_items
    (id, country_code, purpose, pillar, title, description, severity, owner, required_fields_json, citations_json, applies_to_nationality_classes_json, non_obvious, timing, verification_status, review_status, last_verified_at)
VALUES
    ('ie_pps_number_definition', 'IRELAND', 'employment', 'IDENTITY', 'A Personal Public Service (PPS) number is a unique reference number required to access social welfare benefits, public services, and information in Ireland', 'A Personal Public Service (PPS) number is a unique reference number required to access social welfare benefits, public services, and information in Ireland. It is always 7 numbers followed by either one or two letters.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/personal-public-service-number/", "source_name": "citizensinformation.ie", "topic_key": "pps_number", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "Your Personal Public Service (PPS) number is a unique reference number that helps you access social welfare benefits, public services and information in Ireland. A PPS number is always 7 numbers followed by either one or 2 letters.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Must be obtained before starting employment to avoid Emergency Tax.', 'representative', 'pending', NOW()),
    ('ie_pps_number_gateway_services', 'IRELAND', 'employment', 'IDENTITY', 'A PPS number is required to access a wide range of public services in Ireland, including all social welfare services, public health services (including medical card and Drugs Pa…', 'A PPS number is required to access a wide range of public services in Ireland, including all social welfare services, public health services (including medical card and Drugs Payment Scheme), Revenue schemes (e.g. mortgage interest relief), driver theory testing and driving licences, and registration for school or college courses.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/personal-public-service-number/", "source_name": "citizensinformation.ie", "topic_key": "pps_number", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "You need your PPS number for: All social welfare services; The Free Travel Pass; Registering for a course in a school or college; Public health services, including the medical card and the Drugs Payment Scheme; Child immunisation; Schemes run by the Revenue Commissioners, such as mortgage interest relief; Housing grants; Driver theory testing and driving licences.", "added_date": "2026-08-31"}]', NULL, FALSE, 'PPS number must be obtained before any of these services can be accessed.', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_bank_accepted_docs', 'IRELAND', 'employment', 'IDENTITY', 'Documents that banks in Ireland may accept as proof of address include: current utility bill (gas, electricity, or phone), current car or home insurance policy showing the addre…', 'Documents that banks in Ireland may accept as proof of address include: current utility bill (gas, electricity, or phone), current car or home insurance policy showing the address, document issued by a government department, copy of a Tax Credit Certificate, and Statement of Liability from Revenue.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/money-and-tax/personal-finance/banking/financial-institutions-and-identification/", "source_name": "citizensinformation.ie", "topic_key": "proof_of_address", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "Examples of documents that banks may accept as proof of your address include: Current utility bill (such as a gas, electricity or phone bill); Current car or home insurance policy that shows your address; Document issued by a government department that shows your address; Copy of your Tax Credit Certificate (TCC); Statement of Liability from Revenue.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Must be less than 6 months old (or 12 months for insurance) at time of bank account application.', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_bank_account_documents', 'IRELAND', 'employment', 'IDENTITY', 'Banks in Ireland require at least one form of photographic ID and at least one separate proof-of-address document to open a current account', 'Banks in Ireland require at least one form of photographic ID and at least one separate proof-of-address document to open a current account. These two documents must be different — the same document cannot serve as both. The proof-of-address document must be less than 6 months old (or 12 months for an insurance policy).', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/money-and-tax/personal-finance/banking/financial-institutions-and-identification/", "source_name": "citizensinformation.ie", "topic_key": "proof_of_address", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "When you are opening an account, you will need at least one form of photographic identification (photo ID) to prove your identity and at least one document to prove your address. You cannot use the same document as proof of both your identity and your address... Your proof of address must be less than 6 months old (or 12 months for an insurance policy).", "added_date": "2026-08-31"}]', NULL, FALSE, 'Proof-of-address must be less than 6 months old at time of bank account application.', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_breakers_employer_letter', 'IRELAND', 'employment', 'IDENTITY', 'Practical documents that can break the proof-of-address circular dependency for new arrivals include: a signed lease or tenancy agreement, an employer letter confirming the empl…', 'Practical documents that can break the proof-of-address circular dependency for new arrivals include: a signed lease or tenancy agreement, an employer letter confirming the employee''s address, a government letter, a Revenue letter, a bank statement from a foreign account, or a letter from the person the applicant is staying with plus that person''s household bill.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.moneymadeclear.ie/opening-a-bank-account-in-ireland", "source_name": "moneymadeclear.ie", "topic_key": "proof_of_address", "domain_area": "registration/identity", "source_tier": "unofficial", "evidence_quote": "Practical documents that may help include a signed lease, employer letter, government letter, Revenue letter, bank statement from another account, or a letter from the person you are staying with plus their household bill.", "added_date": "2026-08-31"}]', NULL, TRUE, 'An employer letter confirming address can be requested from the employer before the employee''s first day and used immediately to apply for a PPSN appointment.', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_circular_dependency', 'IRELAND', 'employment', 'IDENTITY', 'New arrivals in Ireland face a circular dependency: obtaining a PPS number requires proof of address; opening a traditional bank account requires proof of address; and many tena…', 'New arrivals in Ireland face a circular dependency: obtaining a PPS number requires proof of address; opening a traditional bank account requires proof of address; and many tenancy agreements are easier to secure with a bank account. A new arrival may arrive with none of these documents established at an Irish address.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.moneymadeclear.ie/opening-a-bank-account-in-ireland", "source_name": "moneymadeclear.ie", "topic_key": "proof_of_address", "domain_area": "registration/identity", "source_tier": "unofficial", "evidence_quote": "New arrivals often need a bank account to rent, but need an address to open a bank account. Practical documents that may help include a signed lease, employer letter, government letter, Revenue letter, bank statement from another account, or a letter from the person you are staying with plus their household bill.", "added_date": "2026-08-31"}]', NULL, TRUE, 'This circular dependency is encountered immediately upon arrival, before any Irish utility bills, bank statements, or government letters exist.', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_friend_relative_note', 'IRELAND', 'employment', 'IDENTITY', 'If a new arrival is staying with friends or relatives and has no utility bills in their own name, they can use an original household bill in the bill-holder''s name plus a writte…', 'If a new arrival is staying with friends or relatives and has no utility bills in their own name, they can use an original household bill in the bill-holder''s name plus a written note from the bill-holder confirming the applicant lives at that address. The note can be written on the bill itself.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/personal-public-service-number/", "source_name": "citizensinformation.ie", "topic_key": "proof_of_address", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "If you are staying with friends or relatives, you can use an original household bill, plus a note from the bill holder confirming your residency at the bill address. This note can be written on the bill itself.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Can be used at time of PPSN appointment as an alternative to a bill in the applicant''s own name.', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_government_vs_bank_standards', 'IRELAND', 'employment', 'IDENTITY', 'The DSP (for PPSN) and banks apply different proof-of-address standards', 'The DSP (for PPSN) and banks apply different proof-of-address standards. The DSP explicitly accepts a ''third-party confirmation of address'' (e.g. from a hotel administrator or landlord) and allows a bill-holder note for shared accommodation; banks generally require government-issued or utility documents and do not list the same third-party confirmation workarounds.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/service/12e6de-get-a-personal-public-service-pps-number/", "source_name": "gov.ie", "topic_key": "proof_of_address", "domain_area": "registration/identity", "source_tier": "official", "evidence_quote": "official confirmation of address by a third party; If you are staying with friends or relatives, an original household bill together with a note from the bill holder confirming that you live at the address on the bill is acceptable. This note can be written on the bill itself.", "added_date": "2026-08-31"}]', NULL, TRUE, 'The DSP''s broader acceptance of third-party confirmation means the PPSN appointment may be achievable before a formal bank account or lease is in place.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_definition', 'IRELAND', 'employment', 'IDENTITY', 'The Public Services Card (PSC) is an identity card issued by the Department of Social Protection that proves a person''s identity and enables access to a range of public services', 'The Public Services Card (PSC) is an identity card issued by the Department of Social Protection that proves a person''s identity and enables access to a range of public services. It displays the holder''s name, photograph, signature, card expiry date on the front, and their PPS number, card number, and a magnetic stripe on the back.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/public-services-card/", "source_name": "citizensinformation.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "A Public Services Card proves your identity to help you access a range of public services such as getting social welfare payments... The front of the card has your name, photograph and signature, and the card expiry date. The back of the card has your PPS number and a card number. It also holds a magnetic stripe to enable social welfare payments such as pensions to be collected at post offices.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Usually issued when a PPS number is allocated; can also be obtained subsequently via SAFE registration.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_documents_in_person', 'IRELAND', 'employment', 'IDENTITY', 'At an in-person SAFE registration appointment for a PSC, applicants must bring: the appointment confirmation letter, their Social Services Card (if they have one), documents to …', 'At an in-person SAFE registration appointment for a PSC, applicants must bring: the appointment confirmation letter, their Social Services Card (if they have one), documents to prove identity, documents to prove address, and their mobile phone (so the number can be verified by DSP at the appointment).', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/department-of-social-protection/publications/safe-registration-and-the-public-services-card-psc/", "source_name": "gov.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "official", "evidence_quote": "You will need to bring: the letter confirming your appointment (if you received one); your Social Services Card (if you have one); documents to prove your identity; documents to prove your address; your mobile phone (if you have one). If you bring your mobile phone with you, your phone number can be verified by the department. You can then use your verified mobile phone to create and verify a MyGovID account to securely access public services online.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Bringing the mobile phone to the appointment allows phone verification in a single visit, enabling MyGovID account verification without a separate call later.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_mygovid_verified', 'IRELAND', 'employment', 'IDENTITY', 'Holding a Public Services Card enables a person to upgrade their MyGovID account to ''verified'' level, which unlocks full online access to government services including viewing a…', 'Holding a Public Services Card enables a person to upgrade their MyGovID account to ''verified'' level, which unlocks full online access to government services including viewing and managing claims, payment history, and all online MyWelfare services. A verified mobile phone number (verified by DSP) is also required.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://services.mywelfare.ie/en/topics/identity-services/verify-your-mygovid-account/", "source_name": "services.mywelfare.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "official", "evidence_quote": "In order to verify your MyGovID account you will need the following: A basic MyGovID account; A Public Services Card; A phone that has been verified with the Department of Social Protection. Advantages of having a verified account include: View and manage your claims online; View your payment history; Safe and secure interaction with officers; Access all online MyWelfare services; Shorter and quicker personalised application and renewal forms.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Verified MyGovID can only be obtained after PSC is issued; basic MyGovID account is a prerequisite for booking the PPSN appointment itself.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_mygovid_verify_steps', 'IRELAND', 'employment', 'IDENTITY', 'To verify a MyGovID account using a PSC: log on to MyGovID with the basic account, click ''Verify Your Account'', input PSC card information, and enter the 6-digit code sent to th…', 'To verify a MyGovID account using a PSC: log on to MyGovID with the basic account, click ''Verify Your Account'', input PSC card information, and enter the 6-digit code sent to the verified mobile phone number.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://services.mywelfare.ie/en/topics/identity-services/verify-your-mygovid-account/", "source_name": "services.mywelfare.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "official", "evidence_quote": "To verify your MyGovID account Log on to MyGovID with your basic account; Click on Verify Your Account button; Input your PSC card information; A code will be sent to your verified mobile phone number. Once you receive this 6-digit code, input the code and you will now have a verified account.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Can be completed online once PSC has been received by post and mobile number has been verified with DSP.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_psc_sequence', 'IRELAND', 'employment', 'IDENTITY', 'The recommended sequence for a new arrival is: (1) establish Irish address, (2) obtain PPSN (requires proof of address and identity), (3) register for basic MyGovID, (4) complet…', 'The recommended sequence for a new arrival is: (1) establish Irish address, (2) obtain PPSN (requires proof of address and identity), (3) register for basic MyGovID, (4) complete SAFE registration to receive PSC, (5) use PSC to upgrade to verified MyGovID, enabling full online government service access. The PSC is commonly issued alongside the initial PPSN allocation.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/public-services-card/", "source_name": "citizensinformation.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "A Public Services Card is usually issued when you are allocated a PPS number.", "added_date": "2026-08-31"}]', NULL, TRUE, 'PSC is typically issued at the same time as the PPSN, but the MyGovID verification step requires the PSC to have been received by post and a verified mobile number.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_residency_required', 'IRELAND', 'employment', 'IDENTITY', 'A person must be resident in Ireland to get SAFE registered', 'A person must be resident in Ireland to get SAFE registered. A Public Services Card will only be issued to an Irish address. This means the PSC cannot be obtained before arriving in Ireland.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/department-of-social-protection/publications/safe-registration-and-the-public-services-card-psc/", "source_name": "gov.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "official", "evidence_quote": "You must be resident in Ireland to get SAFE registered. A PSC will only be issued to an Irish address.", "added_date": "2026-08-31"}]', NULL, TRUE, 'PSC application must wait until the employee has established an Irish address.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_safe_registration', 'IRELAND', 'employment', 'IDENTITY', 'SAFE (Standard Authentication Framework Environment) registration is the identity-verification process used by the Department of Social Protection before a Public Services Card …', 'SAFE (Standard Authentication Framework Environment) registration is the identity-verification process used by the Department of Social Protection before a Public Services Card is issued. It takes approximately 15 minutes and involves a photograph being taken and a signature recorded. The completed PSC is then posted to the applicant''s home address.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/department-of-social-protection/publications/safe-registration-and-the-public-services-card-psc/", "source_name": "gov.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "official", "evidence_quote": "SAFE (Standard Authentication Framework Environment) Registration is the process used by the department to verify your identity. Once your identity has been verified we will issue you with a Public Services Card (PSC)... Your SAFE Registration appointment will take about 15 minutes to complete and usually takes place in a PSC/SAFE Registration Centre. During this appointment: your photograph will be taken, and your signature will be recorded.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Must be resident in Ireland before SAFE registration; PSC will only be issued to an Irish address.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_social_welfare_compliance', 'IRELAND', 'employment', 'IDENTITY', 'SAFE registration and PSC are required for authenticating identity for social welfare payments', 'SAFE registration and PSC are required for authenticating identity for social welfare payments. If an individual does not comply with the SAFE registration process when requested, their social welfare payments (including Child Benefit) and/or social welfare entitlements (such as Free Travel) may be suspended.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/public-services-card/", "source_name": "citizensinformation.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "If you comply with the SAFE registration process when requested, you are considered to have authenticated your identity. If you do not comply with the SAFE registration process, your social welfare payments (including Child Benefit) and/or your social welfare entitlements (such as Free Travel) may be suspended.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Compliance with SAFE registration is required when requested by DSP; failure can trigger payment suspension.', 'representative', 'pending', NOW()),
    ('ie_public_services_card_two_registration_routes', 'IRELAND', 'employment', 'IDENTITY', 'There are two ways to obtain a Public Services Card: (1) via the MyGovID app on a smartphone, which requires holding a current Irish passport, being 16 or over, having a basic M…', 'There are two ways to obtain a Public Services Card: (1) via the MyGovID app on a smartphone, which requires holding a current Irish passport, being 16 or over, having a basic MyGovID account, and being resident in Ireland; or (2) in person at a PSC/SAFE Registration Centre (typically the local Intreo Centre), with a pre-booked appointment.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/social-welfare/irish-social-welfare-system/public-services-card/", "source_name": "citizensinformation.ie", "topic_key": "public_services_card", "domain_area": "registration/identity", "source_tier": "semi_official", "evidence_quote": "You can register for a Public Services Card: Using the MyGovID app; In-person at a Public Services Card (PSC) Centre. The MyGovID app allows you to verify your identity using your smartphone. You can download the MyGovID app on your smartphone, if you: Are resident in Ireland; Hold a current Irish passport; Are aged 16 years and over; Have a basic MyGovID account; Have not already completed the SAFE Registration process.", "added_date": "2026-08-31"}]', NULL, TRUE, 'App route requires a current Irish passport; non-Irish-passport holders must attend in person.', 'representative', 'pending', NOW()),
    ('ie_rental_market_above_asking_bidding', 'IRELAND', 'employment', 'HOUSING', 'In Dublin, the advertised rental price is typically the floor, not the ceiling', 'In Dublin, the advertised rental price is typically the floor, not the ceiling. Bidding above the asking price has become common as demand far exceeds supply. HR teams should budget above the listed rent when planning relocation packages for Dublin, and employees should not expect to negotiate downward.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.reddit.com/r/ireland/comments/1l5kgra/are_we_offering_landlords_more_than_the_asking/", "source_name": "reddit.com", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "Severe shortage means even with our crazy prices, some tenants are desperate enough to pay more to secure a place.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Bidding environment varies by season; typically most intense August–October (academic year start) and January–March.', 'representative', 'pending', NOW()),
    ('ie_rental_market_average_rent_2025', 'IRELAND', 'employment', 'HOUSING', 'Nationwide average open-market rents in Ireland surpassed €2,000 per month in early 2025, with Dublin rents growing at 5.8% year-on-year in Q1 2025', 'Nationwide average open-market rents in Ireland surpassed €2,000 per month in early 2025, with Dublin rents growing at 5.8% year-on-year in Q1 2025. Employer relocation packages must account for this base and should not rely on pre-2024 benchmarks.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.worldpropertyjournal.com/real-estate-news/ireland/dublin/ireland-real-estate-news-ireland-2025-rental-home-data-daftie-2025-rental-report-dublin-home-rents-in-2025-ronan-lyons-14451.php", "source_name": "orldpropertyjournal.com", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "Ireland''s rental market continues to tighten dramatically, with average open-market rents nationwide surging to €2,053 per month in the...", "added_date": "2026-08-31"}]', NULL, FALSE, 'Market data as of Q1 2025; verify against current RTB/ESRI Rent Index before employee briefing.', 'representative', 'pending', NOW()),
    ('ie_rental_market_deposit_advance_rent', 'IRELAND', 'employment', 'HOUSING', 'Relocating employees typically face upfront cash requirements of at least two months'' rent: one month''s deposit (the legal maximum a landlord may request) plus one month''s rent …', 'Relocating employees typically face upfront cash requirements of at least two months'' rent: one month''s deposit (the legal maximum a landlord may request) plus one month''s rent in advance. Some landlords request first and last month''s rent in addition to deposit, although charging more than one month as deposit is unlawful under the Residential Tenancies Act. Relocation packages must budget for this initial outlay.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://rtb.ie/renting/rights-responsibilities/security-deposits/", "source_name": "rtb.ie", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "official", "evidence_quote": "A landlord cannot ask for a deposit that is more than one month''s rent. The agreed amount should be documented, and both the tenant and landlord should get a signed and dated receipt.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Upfront funds must be available at point of lease signing; employees without Irish bank accounts should arrange an international transfer or employer advance.', 'representative', 'pending', NOW()),
    ('ie_rental_market_deposit_dispute_volume', 'IRELAND', 'employment', 'HOUSING', 'Deposit-related disputes are the most common category of RTB dispute cases', 'Deposit-related disputes are the most common category of RTB dispute cases. The RTB logged over 1,800 deposit-related requests in 2024 — a 65% increase on the 2021 figure. HR teams should brief relocating employees on how to protect their deposit from day one (document property condition with photographs, retain all written correspondence).', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.thejournal.ie/renter-deposit-scheme-where-is-it-6808628-Sep2025/", "source_name": "thejournal.ie", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "The Residential Tenancies Board (RTB) logged over 1,800 deposit-related requests in 2024 — a 65% increase on the 2021 figure.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Deposit documentation should happen on move-in day; end-of-tenancy dispute must be filed with RTB within the statutory time limit.', 'representative', 'pending', NOW()),
    ('ie_rental_market_dublin_scarcity', 'IRELAND', 'employment', 'HOUSING', 'Dublin''s rental market is among the most competitive in Europe', 'Dublin''s rental market is among the most competitive in Europe. Available stock is extremely scarce — Ireland''s national rental vacancy rate is approximately 1–2%, with Dublin closer to 1%. Properties in desirable Dublin postcodes regularly receive multiple applications within 24–48 hours of listing, and relocating employees should expect intense competition.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://rentalize.com/ireland-rental-market-2026-supply-crisis/", "source_name": "rentalize.com", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "Ireland''s rental vacancy rate sits at roughly 1% to 2% nationally. In Dublin, it is closer to 1%.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Employees should begin searching 8–12 weeks before the intended move-in date; strong candidates may still need temporary accommodation as a bridge.', 'representative', 'pending', NOW()),
    ('ie_rental_market_dublin_vs_regions', 'IRELAND', 'employment', 'HOUSING', 'Dublin is distinctly more competitive and expensive than Ireland''s other cities', 'Dublin is distinctly more competitive and expensive than Ireland''s other cities. Cork, Limerick, and Galway also have tight markets but with greater stock availability and lower average rents than Dublin. HR teams placing employees outside Dublin should still plan for competitive conditions but can reasonably expect a wider range of options and less above-asking bidding pressure.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.globalpropertyguide.com/europe/ireland/price-history", "source_name": "globalpropertyguide.com", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "Dublin remained the dominant market, accounting for 34% of all residential transactions, with 25,104 properties sold in 2025, up 5.66% year on...", "added_date": "2026-08-31"}]', NULL, FALSE, 'Regional market conditions change seasonally; verify with RTB/ESRI Rent Index for the specific city before employee brief.', 'representative', 'pending', NOW()),
    ('ie_rental_market_references_catchtwentytwo', 'IRELAND', 'employment', 'HOUSING', 'Irish landlords commonly require: an employer reference letter, a previous landlord reference, and evidence of an Irish bank account', 'Irish landlords commonly require: an employer reference letter, a previous landlord reference, and evidence of an Irish bank account. This creates a ''catch-22'' for new international arrivals who have not yet opened an Irish bank account or built a local rental history. Employers should provide a formal reference letter on company letterhead confirming employment, salary, and start date before the employee arrives.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.expatfocus.com/ireland/guide/ireland-property-rental-prices", "source_name": "expatfocus.com", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "Most landlords will expect proof of identity (a passport or national identity card), evidence of income or employment, and references from former landlords.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Employer reference letter should be prepared and issued before or at time of arrival; Irish bank account opening should be prioritised in first week.', 'representative', 'pending', NOW()),
    ('ie_rental_market_scam_warning', 'IRELAND', 'employment', 'HOUSING', 'Rental scams are a significant risk in Ireland''s tight market', 'Rental scams are a significant risk in Ireland''s tight market. Key red flags: (1) being asked to pay a deposit before viewing the property in person; (2) advertised rents substantially below market rate; (3) landlord unable or unwilling to provide an RTB registration number; (4) pressure to pay immediately via wire transfer or cryptocurrency. Employees should never transfer money before signing a written tenancy agreement.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://rtb.ie/renting/rights-responsibilities/security-deposits/", "source_name": "rtb.ie", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "official", "evidence_quote": "You should only pay the deposit once you are satisfied with the property and rental terms. Avoid paying in cash (if possible) and always request a receipt.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Most relevant during initial search phase, especially for employees searching remotely from outside Ireland before arrival.', 'representative', 'pending', NOW()),
    ('ie_rental_market_temporary_accommodation', 'IRELAND', 'employment', 'HOUSING', 'Given Dublin''s scarcity, relocation packages for Ireland should include a temporary accommodation budget (serviced apartments or extended-stay hotels) for a minimum of 4–8 weeks…', 'Given Dublin''s scarcity, relocation packages for Ireland should include a temporary accommodation budget (serviced apartments or extended-stay hotels) for a minimum of 4–8 weeks after arrival, as finding permanent rental accommodation typically takes longer than in other EU markets. A week''s extension of temporary corporate housing in Dublin can cost up to approximately €1,200 for a one-bedroom unit.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.altairglobal.com/consulting-corner/ireland-housing-market-case-study/", "source_name": "altairglobal.com", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "for employees relocating to work in Ireland, a week''s extension of temporary corporate housing accommodation can cost up to €1,200 for a one-bedroom", "added_date": "2026-08-31"}]', NULL, FALSE, 'Temporary accommodation budget should be built into relocation package design; 4-week minimum recommended, 8-week buffer preferred for Dublin placements.', 'representative', 'pending', NOW()),
    ('ie_medical_card_apply_online', 'IRELAND', 'employment', 'HEALTHCARE', 'The primary application route for a medical card or GP visit card is online at mymedicalcard.ie (also accessible via medicalcard.ie)', 'The primary application route for a medical card or GP visit card is online at mymedicalcard.ie (also accessible via medicalcard.ie). Applicants need their PPS number, proof of address, and income details. Paper applications (MC1 form) are also available.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/health/medical-cards-and-gp-visit-cards/medical-card/", "source_name": "citizensinformation.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "Apply online for a medical card and GP visit card on mymedicalcard.ie. This is the quickest method of getting the card.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Apply as soon as PPS number and proof of address are available (typically within weeks of arrival).', 'representative', 'pending', NOW()),
    ('ie_medical_card_gp_visit_card_distinction', 'IRELAND', 'employment', 'HEALTHCARE', 'The GP visit card has a higher income threshold than the medical card', 'The GP visit card has a higher income threshold than the medical card. An employee above the medical card income limit may still qualify for a GP visit card, which covers free GP visits but not hospital charges, dental, optical, or prescription drugs. The HSE automatically assesses for both cards in a single application.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/health/medical-cards-and-gp-visit-cards/gp-visit-cards/", "source_name": "citizensinformation.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "When you apply for a GP visit card, the HSE will first assess your application for a medical card. If you don''t qualify for a medical card, you will then be assessed for a GP visit card.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Apply simultaneously for both — one application covers both assessments.', 'representative', 'pending', NOW()),
    ('ie_medical_card_income_thresholds_under70', 'IRELAND', 'employment', 'HEALTHCARE', 'Medical card eligibility for under-70s is means-tested against weekly net income', 'Medical card eligibility for under-70s is means-tested against weekly net income. Current thresholds (since November 2023): single person living alone €184/week; couple €266.50/week. GP visit card thresholds are higher: single person living alone €418/week; couple €607/week.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/health/medical-cards-and-gp-visit-cards/medical-card-means-test-under-70s/", "source_name": "citizensinformation.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "Weekly basic rates for under 70s (Gross income less tax, Universal Social Charge and PRSI) Category Medical card aged under 66 [...] Single person living alone €184 [...] Couple, married/cohabiting/civil partners (or single parent with dependent children) €266.50 [...] GP visit card aged under 70 Single person living alone €418 [...] Couple [...] €607", "added_date": "2026-08-31"}]', NULL, FALSE, 'Assessed at time of application; thresholds reviewed periodically — verify current figures on hse.ie before advising.', 'representative', 'pending', NOW()),
    ('ie_medical_card_over70_no_means_test', 'IRELAND', 'employment', 'HEALTHCARE', 'Persons aged over 70 qualify for a GP visit card without a means test', 'Persons aged over 70 qualify for a GP visit card without a means test. They may also qualify for a full medical card depending on income. For most relocating employees this is not directly relevant but may apply to transferring senior executives or spouses.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/health/medical-cards-and-gp-visit-cards/medical-card/", "source_name": "citizensinformation.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "People aged over 70 [...] Medical card [requires] Means test [but] GP visit card [requires] No means test", "added_date": "2026-08-31"}]', NULL, FALSE, 'Applies from age 70 — no waiting period.', 'representative', 'pending', NOW()),
    ('ie_medical_card_plastic_card_paused', 'IRELAND', 'employment', 'HEALTHCARE', 'The HSE has temporarily paused printing physical plastic medical cards, GP visit cards, EHIC, DPS, and Long-Term Illness cards', 'The HSE has temporarily paused printing physical plastic medical cards, GP visit cards, EHIC, DPS, and Long-Term Illness cards. Approved applicants receive a confirmation letter instead, which serves as proof of eligibility. Digital card versions are available on the HSE Health App.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/health/medical-cards-and-gp-visit-cards/medical-card/", "source_name": "citizensinformation.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "The HSE has temporarily paused printing certain plastic health cards including: Medical cards European Health Insurance Cards (EHIC) GP visit cards Drugs Payment Scheme (DPS) cards Long-Term Illness Scheme cards. If you apply for a card and are eligible, you will get a letter confirming your eligibility for the relevant scheme. You can use the letter as proof of eligibility.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Current as of 2026 — check hse.ie for updates on card production resumption.', 'representative', 'pending', NOW()),
    ('ie_medical_card_what_it_covers', 'IRELAND', 'employment', 'HEALTHCARE', 'A medical card entitles the holder to free GP visits (including out-of-hours services), in-patient public hospital services, dental checks, eye tests, ear tests, and prescriptio…', 'A medical card entitles the holder to free GP visits (including out-of-hours services), in-patient public hospital services, dental checks, eye tests, ear tests, and prescription drugs (subject to a prescription charge per item). It is the most comprehensive public health entitlement in Ireland.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.citizensinformation.ie/en/health/health-services/gp-and-hospital-services/gp-services-to-medical-card-holders/", "source_name": "citizensinformation.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "With a medical card, you can get many public services for free. With a GP visit card, you can get free GP visits.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Effective from the date the medical card is granted.', 'representative', 'pending', NOW())
